  "steps": [
    {
      "id": 1,
      "claim": "CT scans are expensive medical procedures.",
      "evidence": "In the United States a typical CT scan costs between $300 and $3,000 depending on body part and facility.",
      "weight": 0.10,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Uninsured individuals must pay the full price of a CT scan out‑of‑pocket.",
      "evidence": "By definition, uninsured patients have no third‑party payer and are billed the provider’s charge in full.",
      "weight": 0.15,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Insured individuals usually have most of the CT cost covered by their health plan.",
      "evidence": "Private and public insurance plans include diagnostic imaging benefits, leaving patients only a copay or deductible that is far lower than the full charge.",
      "weight": 0.15,
      "depends_on": [1]
    },
    {
      "id": 4,
      "claim": "Higher out‑of‑pocket costs are a strong deterrent to accepting non‑emergency medical procedures.",
      "evidence": "The RAND Health Insurance Experiment and many subsequent health‑economics studies found that cost‑sharing reduces utilization of services—including imaging—by 20‑30% when patients face higher out‑of‑pocket payments.",
      "weight": 0.25,
      "depends_on": [2, 3]
    },
    {
      "id": 5,
      "claim": "Empirical studies find lower rates of CT utilization among uninsured patients compared with insured patients.",
      "evidence": "Analyses of the CDC National Inpatient Sample and other hospital discharge databases report that uninsured adults receive 20‑30% fewer diagnostic imaging studies, including CT, than comparable insured adults.",
      "weight": 0.25,
      "depends_on": [4]
    },
    {
      "id": 6,
      "claim": "Therefore, an uninsured person is more likely than an insured person to decline a CT scan.",
      "evidence": "Combining the higher financial barrier (steps 2‑4) with observed lower utilization (step 5) leads to the conclusion that uninsured patients decline CT scans more often.",
      "weight": 0.10,
      "depends_on": [5]
    }
